const aq = $('Fetch Air Quality').first().json;
const c = aq.current;
const chatId = '8113726432';

const aqiLabel = (v) => {
  if (v <= 50)  return '\uD83D\uDFE2 Good';
  if (v <= 100) return '\uD83D\uDFE1 Moderate';
  if (v <= 150) return '\uD83D\uDFE0 Unhealthy for sensitive groups';
  if (v <= 200) return '\uD83D\uDD34 Unhealthy';
  if (v <= 300) return '\uD83D\uDFE3 Very Unhealthy';
  return '\u26AB Hazardous';
};

const ozoneLabel = (v) => {
  if (v < 60)  return '\uD83D\uDFE2 Low';
  if (v < 100) return '\uD83D\uDFE1 Moderate';
  if (v < 140) return '\uD83D\uDFE0 High';
  return '\uD83D\uDD34 Very High';
};

const dustLabel = (v) => {
  if (v < 25)  return '\uD83D\uDFE2 Low';
  if (v < 50)  return '\uD83D\uDFE1 Moderate';
  if (v < 100) return '\uD83D\uDFE0 High';
  return '\uD83D\uDD34 Very High';
};

const pollenLabel = (v) => {
  if (v === null || v === undefined) return '\u26AA N/A';
  if (v < 10)  return '\uD83D\uDFE2 Low (' + v + ')';
  if (v < 50)  return '\uD83D\uDFE1 Moderate (' + v + ')';
  if (v < 200) return '\uD83D\uDFE0 High (' + v + ')';
  return '\uD83D\uDD34 Very High (' + v + ')';
};

const today = new Date().toLocaleDateString('en-US', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric',
  timeZone: 'America/Chicago'
});

const msg = `\uD83C\uDF24 <b>Air Quality Report \u2014 ${today}</b>

\uD83C\uDF0D <b>Overall AQI:</b> ${c.us_aqi} \u2014 ${aqiLabel(c.us_aqi)}
\uD83C\uDF2B <b>PM10:</b> ${c.pm10} \u00B5g/m\u00B3 \u2014 ${dustLabel(c.pm10)}
\uD83D\uDCA8 <b>PM2.5:</b> ${c.pm2_5} \u00B5g/m\u00B3
\uD83E\uDDEA <b>Ozone:</b> ${c.ozone} \u00B5g/m\u00B3 \u2014 ${ozoneLabel(c.ozone)}
\uD83C\uDFDC <b>Dust:</b> ${c.dust} \u00B5g/m\u00B3 \u2014 ${dustLabel(c.dust)}

\uD83C\uDF3F <b>Pollen (grains/m\u00B3)</b>
\uD83C\uDF33 <b>Tree (Birch):</b> ${pollenLabel(c.birch_pollen)}
\uD83C\uDF3E <b>Grass:</b> ${pollenLabel(c.grass_pollen)}
\uD83C\uDF31 <b>Ragweed:</b> ${pollenLabel(c.ragweed_pollen)}

\u2139\uFE0F Source: Open-Meteo (open-meteo.com)`;

return [{ json: { message: msg, chatId } }];
